// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.provider/** * NOUS — Cloud LLM provider configuration. * * Fully customizable: users can add ANY OpenAI-compatible cloud endpoint * (Groq, Together, OpenRouter, Anyscale, Fireworks, Replicate, vLLM, * LM Studio, Ollama, custom self-hosted, etc.) by providing: *   - Base URL *   - API key (stored in CredentialVault, referenced by alias) *   - Model name(s) *   - Optional custom headers (for weird auth schemes) *   - Optional cert pins (SPKI hashes) for security * * ## User Privacy * *   - All cloud providers are DISABLED by default (per ADR 0011 — Maximum *     Privacy Default). User must explicitly opt-in per provider. *   - API keys are NEVER stored in this config — only an alias is stored. *     The actual key lives in [com.roshan.persona.brain.skill.CredentialVaultInterface], *     backed by Android Keystore + EncryptedSharedPreferences in Module 7. *   - When [CloudLlmLayer] makes a call, it looks up the key via the alias *     at call time — keys are never logged, never serialized, never sent *     anywhere except the target provider's API. * * ## Custom Provider Example * * A user adds a self-hosted vLLM endpoint: * * ```kotlin * val customProvider = CloudProviderConfig( *     id = "my-vllm", *     displayName = "My vLLM Server", *     baseUrl = "https://vllm.my-server.com/v1", *     apiKeyAlias = "my-vllm-key",  // user adds key separately in CredentialVault *     apiProtocol = ApiProtocol.OPENAI_COMPATIBLE, *     defaultModel = "meta-llama/Llama-3.1-70B-Instruct", *     availableModels = listOf("meta-llama/Llama-3.1-70B-Instruct", "Qwen/Qwen2.5-72B-Instruct"), *     pricingPer1kTokens = Pricing(inputPer1k = 0f, outputPer1k = 0f),  // self-hosted = free *     maxContextLength = 128_000, *     timeoutMs = 60_000, *     isEnabled = true, *     isBuiltIn = false, *     customHeaders = emptyMap(), *     certPins = listOf("sha256/AAAA...="),  // user's server cert pin * ) * ``` * * @see <a href="docs/spec/module2-spec-review.pdf">§8 Layer 4</a> */data class CloudProviderConfig(    /** Stable unique ID (e.g., "openai", "anthropic", "custom_my-vllm"). */    val id: String,    /** Display name shown in Settings → AI Models → Cloud Providers. */    val displayName: String,    /**     * Base URL for the API (e.g., "https://api.openai.com/v1").     *     * For OpenAI-compatible: should end with `/v1` (or equivalent).     * For Anthropic: should be "https://api.anthropic.com".     * For Gemini: should be "https://generativelanguage.googleapis.com".     */    val baseUrl: String,    /**     * Alias for the API key in [com.roshan.persona.brain.skill.CredentialVaultInterface].     *     * NEVER store the actual key here. The alias is just a string identifier     * — the layer looks up the real key via the vault at call time.     */    val apiKeyAlias: String,    /** Which API protocol/shape this provider uses. */    val apiProtocol: ApiProtocol,    /** Default model to use (user can override per-request). */    val defaultModel: String,    /** All models the user has configured for this provider. */    val availableModels: List<String>,    /** Pricing for cost tracking (USD per 1k tokens). */    val pricingPer1kTokens: Pricing,    /** Maximum context length in tokens for the default model. */    val maxContextLength: Int,    /** Per-call timeout in milliseconds. */    val timeoutMs: Long = 30_000L,    /** Whether the user has enabled this provider (default = false per ADR 0011). */    val isEnabled: Boolean = false,    /** True for built-in providers (OpenAI, Anthropic, etc.), false for user-added. */    val isBuiltIn: Boolean = false,    /** Custom HTTP headers (for weird auth schemes — e.g., "X-Custom-Auth"). */    val customHeaders: Map<String, String> = emptyMap(),    /** SPKI cert pin hashes for cert pinning (e.g., "sha256/AAAA...="). */    val certPins: List<String> = emptyList(),    /** When this config was last updated (epoch millis). */    val updatedAtEpochMs: Long = 0L,) {    init {        require(id.isNotBlank()) { "Provider ID cannot be blank" }        require(id.matches(Regex("[a-zA-Z0-9_-]+"))) {            "Provider ID must be alphanumeric + dash/underscore, was: $id"        }        require(displayName.isNotBlank()) { "Display name cannot be blank" }        require(baseUrl.startsWith("https://")) {            "Base URL must use HTTPS (no cleartext cloud calls): $baseUrl"        }        require(defaultModel.isNotBlank()) { "Default model cannot be blank" }        require(maxContextLength in 1..1_000_000) {            "maxContextLength must be 1-1_000_000, was $maxContextLength"        }        require(timeoutMs in 1_000..600_000) {            "timeoutMs must be 1_000-600_000ms, was $timeoutMs"        }        require(pricingPer1kTokens.inputPer1k >= 0f) {            "Input pricing cannot be negative"        }        require(pricingPer1kTokens.outputPer1k >= 0f) {            "Output pricing cannot be negative"        }    }    /**     * Compute the cost in USD for a request with [inputTokens] input and     * [outputTokens] output.     */    fun computeCostUsd(inputTokens: Int, outputTokens: Int): Float {        val inputCost = (inputTokens / 1000f) * pricingPer1kTokens.inputPer1k        val outputCost = (outputTokens / 1000f) * pricingPer1kTokens.outputPer1k        return inputCost + outputCost    }    companion object {        /** Prefix for user-added provider IDs (to distinguish from built-in). */        const val CUSTOM_PREFIX = "custom_"    }}/** * API protocol shape — determines request/response format. * * Most cloud providers (Groq, Together, OpenRouter, vLLM, Ollama, LM Studio) * are OpenAI-compatible. Anthropic and Gemini have unique request shapes. */enum class ApiProtocol {    /**     * OpenAI-compatible — covers 90% of providers including user-hosted ones.     *     * POST /chat/completions     * Body: {"model": "...", "messages": [...], "temperature": ..., "stream": true}     * Auth: Bearer <api_key>     */    OPENAI_COMPATIBLE,    /**     * Anthropic Claude API.     *     * POST /v1/messages     * Body: {"model": "...", "system": "...", "messages": [...], "max_tokens": ...}     * Auth: x-api-key: <api_key>     * Required headers: "anthropic-version: 2023-06-01"     */    ANTHROPIC,    /**     * Google Gemini API.     *     * POST /v1beta/models/{model}:generateContent?key=<api_key>     * Body: {"contents": [...], "systemInstruction": {...}}     * Auth: API key in URL query param (Gemini-specific)     */    GEMINI,}/** * Pricing for LLM calls (USD per 1k tokens). * * Used by [LlmCostTracker] to enforce monthly budget caps. */data class Pricing(    /** USD per 1k input tokens. */    val inputPer1k: Float,    /** USD per 1k output tokens. */    val outputPer1k: Float,) {    companion object {        /** Free — for self-hosted providers (vLLM, Ollama, LM Studio). */        val FREE = Pricing(inputPer1k = 0f, outputPer1k = 0f)        /** OpenAI GPT-4o pricing (as of 2026). */        val GPT_4O = Pricing(inputPer1k = 0.0025f, outputPer1k = 0.01f)        /** OpenAI GPT-4o-mini pricing. */        val GPT_4O_MINI = Pricing(inputPer1k = 0.00015f, outputPer1k = 0.0006f)        /** Anthropic Claude 3.5 Sonnet pricing. */        val CLAUDE_3_5_SONNET = Pricing(inputPer1k = 0.003f, outputPer1k = 0.015f)        /** Google Gemini 1.5 Pro pricing. */        val GEMINI_1_5_PRO = Pricing(inputPer1k = 0.00125f, outputPer1k = 0.005f)        /** Google Gemini 1.5 Flash pricing. */        val GEMINI_1_5_FLASH = Pricing(inputPer1k = 0.000075f, outputPer1k = 0.0003f)        /** Groq (ultra-low-latency) — typically free tier or very cheap. */        val GROQ_FREE = Pricing(inputPer1k = 0f, outputPer1k = 0f)    }}